//! The bundled HSK 3.0 curriculum (decision 9: static reference data that
//! ships with the apps, not a live API).
//!
//! `data/hsk_curriculum.json` is generated by `tools/hsk-import` from a pinned
//! upstream commit; see docs/architecture.md § "HSK curriculum ETL".

use std::collections::HashMap;

use crate::{model::CurriculumItem, providers::CurriculumLookup};

const BUNDLED_JSON: &str = include_str!("../data/hsk_curriculum.json");

/// Parses the curriculum compiled into this crate, ordered by
/// `curriculum_order`.
pub fn bundled_curriculum() -> Result<Vec<CurriculumItem>, serde_json::Error> {
    let mut items: Vec<CurriculumItem> = serde_json::from_str(BUNDLED_JSON)?;
    items.sort_by_key(|item| item.curriculum_order);
    Ok(items)
}

/// In-memory, thread-safe index over curriculum items, keyed by hanzi.
#[derive(Debug, Clone, Default)]
pub struct CurriculumIndex {
    by_hanzi: HashMap<String, CurriculumItem>,
}

impl CurriculumIndex {
    pub fn new(items: impl IntoIterator<Item = CurriculumItem>) -> Self {
        Self {
            by_hanzi: items
                .into_iter()
                .map(|item| (item.hanzi.clone(), item))
                .collect(),
        }
    }

    /// Index over [`bundled_curriculum`]; empty if the bundled file is
    /// missing entries or fails to parse (logged).
    pub fn bundled() -> Self {
        match bundled_curriculum() {
            Ok(items) => Self::new(items),
            Err(err) => {
                log::error!("bundled HSK curriculum failed to parse: {err}");
                Self::default()
            }
        }
    }

    pub fn len(&self) -> usize {
        self.by_hanzi.len()
    }

    pub fn is_empty(&self) -> bool {
        self.by_hanzi.is_empty()
    }
}

impl CurriculumLookup for CurriculumIndex {
    fn lookup(&self, hanzi: &str) -> Option<CurriculumItem> {
        self.by_hanzi.get(hanzi.trim()).cloned()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item(hanzi: &str, order: i64) -> CurriculumItem {
        CurriculumItem {
            hanzi: hanzi.into(),
            traditional: None,
            hsk_level: 1,
            frequency: None,
            curriculum_order: order,
            pinyin: "x".into(),
            pos: None,
            meaning_en: None,
            meaning_de: None,
            cloze_sentence: None,
            example_sentence_source: None,
            example_sentence_pinyin: None,
            example_sentence_target: None,
            vocab_audio_path: None,
            sentence_audio_path: None,
            image_path: None,
        }
    }

    #[test]
    fn bundled_file_parses() {
        assert!(bundled_curriculum().is_ok());
    }

    #[test]
    fn index_looks_up_trimmed_hanzi() {
        let index = CurriculumIndex::new([item("学习", 1), item("你好", 0)]);
        assert_eq!(index.len(), 2);
        assert_eq!(index.lookup(" 学习 ").map(|i| i.curriculum_order), Some(1));
        assert!(index.lookup("没有").is_none());
    }
}
